<?php /** Template Name: Member Reviews @package ForgetFit */ get_header(); $reviews = new WP_Query( array( 'post_type' => 'ff_review', 'posts_per_page' => 12 ) ); ?><main id="main" class="site-main"><header class="inner-hero"><div class="container"><span class="eyebrow"><?php esc_html_e( 'Member stories', 'forgetfit' ); ?></span><h1><?php esc_html_e( 'Real progress, in their words.', 'forgetfit' ); ?></h1><p class="lead"><?php esc_html_e( 'Publish verified member experiences to show what your community is really like.', 'forgetfit' ); ?></p></div></header><section class="section section--cream"><div class="container"><div class="review-grid"><?php if ( $reviews->have_posts() ) : while ( $reviews->have_posts() ) : $reviews->the_post(); ?><blockquote class="review-card"><p>“<?php echo esc_html( get_the_excerpt() ?: wp_trim_words( get_the_content(), 40 ) ); ?>”</p><footer><strong><?php the_title(); ?></strong><span><?php esc_html_e( 'Member review', 'forgetfit' ); ?></span></footer></blockquote><?php endwhile; wp_reset_postdata(); else : ?><div class="empty-state"><h2><?php esc_html_e( 'Add your verified reviews.', 'forgetfit' ); ?></h2><p><?php esc_html_e( 'Use Member Reviews in WordPress to publish genuine social proof.', 'forgetfit' ); ?></p></div><?php endif; ?></div></div></section></main><?php get_footer(); ?>

